/*
 * Linker version script for libzahlen_engine.so (ELF only).
 *
 * The renderer (zahlen_render, which embeds Volk) is linked into the engine
 * shared library AND can additionally end up -- via its static archive --
 * inside executables that link both (tests, extras consumers). Volk's
 * dispatch table is per-image by design (visibility hidden), and its loader
 * entry points (volkInitialize, volkLoadInstance, ...) have default
 * visibility, so in that topology the executable's copy silently preempts
 * the engine's calls: the engine's guard reports success while its own
 * table stays NULL, and the first vk* call jumps to 0x0.
 *
 * Localizing the renderer's symbols in the engine .so binds them internally
 * at link time (no PLT, no preemption): the engine always initializes and
 * uses its own table, and executable-embedded copies (if any) use theirs.
 *
 * Exceptions -- renderer symbols that ARE part of the engine's public
 * surface and must stay exported (first match wins over the local globs
 * below): the validation-accounting counters read by the test framework
 * (tests/TestsFramework.hpp) around every suite. Note: if an executable
 * embeds its own copy of RenderCore.c, its preempted read observes its own
 * (zero) counters rather than the engine's; nothing in-tree does this.
 *
 * Windows PE and macOS two-level namespaces bind intra-image by default and
 * do not need this.
 */
{
    global:
        ZHLN_GetValidationErrorCount;
        ZHLN_GetDeviceLostCount;

    local:
        volk*;
        ZHLN_*;
        vma*;
        _ZN5ZHLN2Vk*;
        _ZN5ZHLN4Vk11*;
};
